-- BHOOK portable database export
-- Generated 2026-09-17T20:53:48.151Z
-- Contains catalog and synthetic price history only; no credentials or OAuth tokens.
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

DROP TABLE IF EXISTS `price_history`;
DROP TABLE IF EXISTS `menu_items`;
DROP TABLE IF EXISTS `restaurants`;

CREATE TABLE `restaurants` (
  `restaurant_id` varchar(10) NOT NULL,
  `name` varchar(255) DEFAULT NULL,
  `city` varchar(100) DEFAULT NULL,
  `area` varchar(100) DEFAULT NULL,
  `cuisines` varchar(255) DEFAULT NULL,
  `restaurant_rating` decimal(2,1) DEFAULT NULL,
  `data_source` enum('mock','swiggy_live','zomato_simulated') NOT NULL DEFAULT 'mock',
  `is_live` tinyint(1) NOT NULL DEFAULT '0',
  `fetched_at` datetime DEFAULT NULL,
  `source_restaurant_id` varchar(191) DEFAULT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  PRIMARY KEY (`restaurant_id`),
  UNIQUE KEY `uq_restaurant_live_area` (`data_source`,`source_restaurant_id`,`area`),
  KEY `idx_restaurant_city_area` (`city`,`area`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `menu_items` (
  `item_id` int NOT NULL AUTO_INCREMENT,
  `restaurant_id` varchar(10) DEFAULT NULL,
  `platform` varchar(20) DEFAULT NULL,
  `item_name` varchar(255) DEFAULT NULL,
  `veg_or_non_veg` varchar(10) DEFAULT NULL,
  `price_inr` int DEFAULT NULL,
  `item_rating` decimal(2,1) DEFAULT NULL,
  `delivery_time_mins` int DEFAULT NULL,
  `image_url` varchar(500) DEFAULT NULL,
  `data_source` enum('mock','swiggy_live','zomato_simulated') NOT NULL DEFAULT 'mock',
  `is_live` tinyint(1) NOT NULL DEFAULT '0',
  `fetched_at` datetime DEFAULT NULL,
  `source_item_id` int DEFAULT NULL,
  `price_offset_percent` decimal(5,2) DEFAULT NULL,
  `external_item_id` varchar(191) DEFAULT NULL,
  PRIMARY KEY (`item_id`),
  UNIQUE KEY `uq_menu_live_item` (`data_source`,`restaurant_id`,`external_item_id`),
  UNIQUE KEY `uq_menu_simulated_source` (`data_source`,`source_item_id`),
  KEY `restaurant_id` (`restaurant_id`),
  KEY `idx_menu_source_item` (`source_item_id`),
  CONSTRAINT `fk_menu_source_item` FOREIGN KEY (`source_item_id`) REFERENCES `menu_items` (`item_id`) ON DELETE CASCADE,
  CONSTRAINT `menu_items_ibfk_1` FOREIGN KEY (`restaurant_id`) REFERENCES `restaurants` (`restaurant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=17528 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `price_history` (
  `history_id` int NOT NULL AUTO_INCREMENT,
  `item_id` int NOT NULL,
  `price_inr` int NOT NULL,
  `recorded_date` date NOT NULL,
  PRIMARY KEY (`history_id`),
  KEY `item_id` (`item_id`),
  CONSTRAINT `price_history_ibfk_1` FOREIGN KEY (`item_id`) REFERENCES `menu_items` (`item_id`)
) ENGINE=InnoDB AUTO_INCREMENT=16377 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

